manifest={}
for path,entries in groups.items():
 raw=(root/path).read_bytes(); src=raw.decode('utf8').splitlines(); digest=hashlib.sha256(raw).hexdigest(); name=path.replace('/','_')+'.md'; out=['# شرح `'+path+'`','',f'بصمة المصدر SHA-256: `{digest}`.','','لم يُنفذ اختبار النشر أو المتصفح في هذه الجلسة.','']
 for a,b,d in entries: out += [f'## الأسطر {a}–{b}','','```python',*src[a-1:b],'```','',d,'']
 (base/'line_by_line'/name).write_text('\n'.join(out),encoding='utf8'); manifest[path]={'document':'line_by_line/'+name,'ranges':[[a,b] for a,b,_ in entries],'sha256':digest,'review':'يدوية غير مستقلة','quote_verification':'آلي'}
(base/'deployment_tests_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf8')
